package kr.moida.calllink;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import android.util.Base64;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public class UploadService extends Service {
 final ScheduledExecutorService executor=Executors.newSingleThreadScheduledExecutor();final Map<String,String> stable=new HashMap<>();boolean started=false;volatile boolean stopped=false;SharedPreferences prefs;
 void status(String s){prefs.edit().putString("status",s).apply();}
 @Override public int onStartCommand(Intent i,int flags,int id){prefs=getSharedPreferences("link",0);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("collect","통화 녹음 자동 수집",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"collect").setContentTitle("모이다 통화 녹음 자동 수집 중").setContentText("새 녹음 파일을 확인합니다. 앱에서 끌 수 있습니다.").setSmallIcon(android.R.drawable.stat_sys_upload).setContentIntent(open).build());if(!started){started=true;executor.scheduleWithFixedDelay(()->{if(stopped)return;try{scan();}catch(Exception e){status("폴더 또는 네트워크 연결을 확인하세요. 다음 확인 때 다시 시도합니다.");}},0,5,TimeUnit.SECONDS);}return START_NOT_STICKY;}
 void scan()throws Exception{String folder=prefs.getString("folder","");if(folder.isEmpty())return;Uri tree=Uri.parse(folder),children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));String[] columns={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED};try(Cursor cursor=getContentResolver().query(children,columns,null,null,null)){if(cursor==null)return;while(!stopped&&cursor.moveToNext()){String id=cursor.getString(0),name=cursor.getString(1);long size=cursor.getLong(2),modified=cursor.getLong(3);if(name==null||!name.matches("(?i).+\\.(m4a|mp3|wav|mp4|mpeg|mpga|webm)$")||size<=0||modified<=prefs.getLong("since",Long.MAX_VALUE))continue;String stamp=size+":"+modified,key="sent_"+id;if(stamp.equals(prefs.getString(key,"")))continue;if(size>24L*1024*1024){status(name+" · 24MB를 초과했습니다. 모이다에서 나누어 올려 주세요.");continue;}String old=stable.put(id,stamp);if(!stamp.equals(old)||System.currentTimeMillis()-modified<10000)continue;status(name+" · 녹음 업로드 중");Uri file=DocumentsContract.buildDocumentUriUsingTree(tree,id);String result=upload(file,name,size);prefs.edit().putString(key,stamp).apply();status(name+" · 업로드 완료 · 서버에서 자동 전사·요약 중.");}}}
 String upload(Uri uri,String name,long size)throws Exception{String boundary="Moida"+UUID.randomUUID().toString().replace("-","");HttpURLConnection connection=(HttpURLConnection)new URL("https://moida-gpt.banedict84.workers.dev/call-recordings/upload").openConnection();connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setConnectTimeout(30000);connection.setReadTimeout(420000);connection.setRequestProperty("Authorization","Basic "+Base64.encodeToString(prefs.getString("code","").getBytes(StandardCharsets.UTF_8),Base64.NO_WRAP));connection.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);connection.setChunkedStreamingMode(65536);try{try(OutputStream out=connection.getOutputStream();InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();String filename=name.replace("\"","").replace("\r","").replace("\n","");out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+filename+"\"\r\nContent-Type: application/octet-stream\r\n\r\n").getBytes(StandardCharsets.UTF_8));byte[] buffer=new byte[65536];int n;long total=0;while((n=in.read(buffer))!=-1){total+=n;if(stopped||total>24L*1024*1024)throw new IOException();out.write(buffer,0,n);}out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));}int code=connection.getResponseCode();if(code==401){status("모이다 연결 코드가 만료·해제되었습니다. 다시 연결하세요.");stopSelf();throw new IOException();}if(code!=200)throw new IOException();try(InputStream in=connection.getInputStream()){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(data.size()>1048576)throw new IOException();data.write(b,0,n);}return data.toString("UTF-8");}}finally{connection.disconnect();}}
 @Override public void onDestroy(){stopped=true;executor.shutdownNow();super.onDestroy();}@Override public IBinder onBind(Intent intent){return null;}
}

